        public string GetplateType = "CREATE PROCEDURE [dbo].[GetplateType]\r\n\r\n\t\r\nAS\r\nBEGIN\r\n\tSET NOCOUNT ON;\r\n\t\r\nSELECT [Plate_type_id]\r\n      ,[Plate_type_name]\r\n      ,[Status]\r\n  FROM [dbo].[Plate_type]\r\nEND";
